if __name__ == "__main__":
    import sys
    batch = [json.loads(l)["mid"] for l in open(f"data/z52b/pass1/batch_{B}.jsonl")]
    have = {r["mid"]: r for r in R}
    missing = [m for m in batch if m not in have]
    extra = [m for m in have if m not in batch]
    print("batch", len(batch), "outcomes", len(R), "missing", len(missing), missing[:50], "extra", extra)
    if "--write" in sys.argv:
        with open(f"data/z52b/pass1/outcome_{B}.jsonl", "w") as f:
            for m in batch:
                if m in have:
                    f.write(json.dumps(have[m], ensure_ascii=False) + "\n")
